package com.nexusdrive.metadata.controller;import com.nexusdrive.common.dto.ApiResponse;import com.nexusdrive.common.security.CustomUserDetails;import com.nexusdrive.metadata.dto.*;import com.nexusdrive.metadata.service.FileMetadataService;import io.swagger.v3.oas.annotations.Operation;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;@RestController@RequestMapping("/api/files")public class FileController{private final FileMetadataService files;public FileController(FileMetadataService f){files=f;}@Operation(summary="Initialize a resumable upload")@PostMapping(value="/upload",consumes=MediaType.APPLICATION_JSON_VALUE)@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<FileResponse> init(@AuthenticationPrincipal CustomUserDetails u,@Valid@RequestBody FileUploadRequest r){return ApiResponse.ok(FileResponse.from(files.initialize(u.userId(),r)));}@Operation(summary="Upload a complete file as a bounded-memory stream")@PostMapping(value="/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<FileResponse> upload(@AuthenticationPrincipal CustomUserDetails u,@RequestPart MultipartFile file,@RequestParam(required=false)UUID folderId,@RequestParam(required=false)List<String> tags)throws Exception{return ApiResponse.ok(FileResponse.from(files.upload(u.userId(),file.getOriginalFilename(),Optional.ofNullable(file.getContentType()).orElse("application/octet-stream"),folderId,tags==null?new String[0]:tags.toArray(String[]::new),file.getInputStream(),file.getSize())));}@Operation(summary="Upload one indexed plaintext chunk")@PostMapping(value="/{id}/chunks/{index}",consumes=MediaType.APPLICATION_OCTET_STREAM_VALUE)@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<Void> chunk(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id,@PathVariable int index,@RequestBody byte[] data){files.uploadChunk(u.userId(),id,index,data);return ApiResponse.ok(null,"Chunk accepted");}@Operation(summary="Get resumable upload status")@GetMapping("/{id}/chunks/status")public ApiResponse<ChunkStatusResponse> status(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id){return ApiResponse.ok(files.status(u.userId(),id));}@Operation(summary="Stream a decrypted file")@GetMapping("/{id}/download")public ResponseEntity<StreamingResponseBody> download(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id){var f=files.getAccessible(u.userId(),id);StreamingResponseBody body=out->files.download(u.userId(),id,out);return ResponseEntity.ok().contentLength(f.getSizeBytes()).contentType(MediaType.parseMediaType(f.getMimeType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename*=UTF-8''"+java.net.URLEncoder.encode(f.getFilename(),java.nio.charset.StandardCharsets.UTF_8)).body(body);}@Operation(summary="Logically delete a file")@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','USER')")public ApiResponse<Void> delete(@AuthenticationPrincipal CustomUserDetails u,@PathVariable UUID id){files.delete(u.userId(),id);return ApiResponse.ok(null,"Deleted");}}
